'use strict';

/**
* Default Xorshift128+ PRNG instance.
*
* Note: This file is provided for backward compatibility with stdlib patterns.
* Most users should use the factory directly via index.js.
*/

// MODULES //

var factory = require( './factory.js' );
var randi32 = require( './rand_int64.js' );


// MAIN //

/**
* Default Xorshift128+ PRNG instance.
*
* This is a pre-created PRNG instance with a random seed.
* It can be used directly for generating random numbers.
*
* @name xorshift128plus
* @type {Function}
* @returns {bigint} pseudorandom 64-bit unsigned integer
*
* @example
* var xorshift128plus = require( '@stdlib/random/base/xorshift128/lib/main.js' );
*
* var v = xorshift128plus();
* // returns <bigint>
*
* var v = xorshift128plus.normalized();
* // returns <number>
*/
var xorshift128plus = factory({
	'seed': randi32()
});


// EXPORTS //

module.exports = xorshift128plus;
